187	    /**
188	     * Normalize a value for household-identity comparison: null becomes an empty
189	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
190	     * to a single space, and the result is lower-cased.
191	     */
192	    private static String normalizeIdentity(String value) {
193	        if (value == null) {
194	            return "";
195	        }
196	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
197	    }
