199	    /**
200	     * Build the stable, shared household identifier for an owner, formatted
201	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
202	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
203	     * Owners in the same household (same normalized lastName and address) therefore
204	     * derive an identical householdId.
205	     */
206	    private static String householdId(String lastNameKey, String addressKey) {
207	        String source = lastNameKey + "|" + addressKey;
208	        try {
209	            byte[] digest = MessageDigest.getInstance("SHA-256")
210	                .digest(source.getBytes(StandardCharsets.UTF_8));
211	            StringBuilder sb = new StringBuilder(digest.length * 2);
212	            for (byte b : digest) {
213	                sb.append(String.format("%02x", b));
214	            }
215	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
216	        }
217	        catch (NoSuchAlgorithmException e) {
218	            throw new IllegalStateException("SHA-256 not available", e);
219	        }
220	    }
