224	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
225	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
226	     * sequence equal to one more than the number of owners already in that city
227	     * (e.g. 'LON-SMI-0007').
228	     */
229	    private String nextCustomerCode(String city, String lastName) {
230	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
231	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
232	        String cityKey = normalizeIdentity(city);
233	        int sequence = (int) this.clinicService.findAllOwners().stream()
234	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
235	            .count() + 1;
236	        return String.format("%s-%s-%04d", city3, last3, sequence);
237	    }
