239	    /**
240	     * Build the membership number assigned on create, formatted
241	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
242	     * {@code registrationDate} year (e.g. 'LON-SMI-0007-M26').
243	     */
244	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
245	        String yy = String.format("%02d", registrationDate.getYear() % 100);
246	        return customerCode + "-M" + yy;
247	    }
