60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Minimal syntactic check for an email address: a non-empty local part, a single
66	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final TelephoneNormalizer telephoneNormalizer;
79	
80	    private final AddressNormalizer addressNormalizer;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper,
86	                                 TelephoneNormalizer telephoneNormalizer,
87	                                 AddressNormalizer addressNormalizer) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	        this.telephoneNormalizer = telephoneNormalizer;
93	        this.addressNormalizer = addressNormalizer;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        if (owner.getRegistrationDate() == null) {
127	            owner.setRegistrationDate(LocalDate.now());
128	        }
129	        String address = addressNormalizer.normalize(owner.getAddress());
130	        if (address.isBlank()) {
131	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
132	        }
133	        owner.setAddress(address);
134	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
135	        if (telephone == null) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        owner.setTelephone(telephone);
139	        String email = owner.getEmail();
140	        if (email != null) {
141	            email = email.trim();
142	            if (!EMAIL_PATTERN.matcher(email).matches()) {
143	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
144	            }
145	            owner.setEmail(email.toLowerCase(Locale.ROOT));
146	        }
147	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
148	            .map(Owner::getTelephone)
149	            .filter(Objects::nonNull)
150	            .map(telephoneNormalizer::normalize)
151	            .anyMatch(telephone::equals);
152	        if (telephoneInUse) {
153	            return new ResponseEntity<>(HttpStatus.CONFLICT);
154	        }
155	        String cityKey = normalizeIdentity(owner.getCity());
156	        long ownersInCity = this.clinicService.findAllOwners().stream()
157	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
158	            .count();
159	        if (ownersInCity >= 50) {
160	            return new ResponseEntity<>(HttpStatus.CONFLICT);
161	        }
162	        String lastNameKey = normalizeIdentity(owner.getLastName());
163	        String addressKey = addressNormalizer.normalize(owner.getAddress());
164	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
165	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
166	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
167	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
168	            if (householdDuplicate) {
169	                return new ResponseEntity<>(HttpStatus.CONFLICT);
170	            }
171	        }
172	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
173	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
174	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
175	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
176	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
177	            .count();
178	        owner.setNamesakeCount(namesakeCount);
179	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
180	        this.clinicService.saveOwner(owner);
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        headers.setLocation(UriComponentsBuilder.newInstance()
183	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
184	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    /**
188	     * Normalize a value for household-identity comparison: null becomes an empty
189	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
190	     * to a single space, and the result is lower-cased.
191	     */
192	    private static String normalizeIdentity(String value) {
193	        if (value == null) {
194	            return "";
195	        }
196	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
197	    }
198	
199	    /**
200	     * Build the stable, shared household identifier for an owner, formatted
201	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
202	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
203	     * Owners in the same household (same normalized lastName and address) therefore
204	     * derive an identical householdId.
205	     */
206	    private static String householdId(String lastNameKey, String addressKey) {
207	        String source = lastNameKey + "|" + addressKey;
208	        try {
209	            byte[] digest = MessageDigest.getInstance("SHA-256")
210	                .digest(source.getBytes(StandardCharsets.UTF_8));
211	            StringBuilder sb = new StringBuilder(digest.length * 2);
212	            for (byte b : digest) {
213	                sb.append(String.format("%02x", b));
214	            }
215	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
216	        }
217	        catch (NoSuchAlgorithmException e) {
218	            throw new IllegalStateException("SHA-256 not available", e);
219	        }
220	    }
221	
222	    /**
223	     * Build the customer code assigned on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
224	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
225	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
226	     * sequence equal to one more than the number of owners already in that city
227	     * (e.g. 'LON-SMI-0007').
228	     */
229	    private String nextCustomerCode(String city, String lastName) {
230	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
231	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
232	        String cityKey = normalizeIdentity(city);
233	        int sequence = (int) this.clinicService.findAllOwners().stream()
234	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
235	            .count() + 1;
236	        return String.format("%s-%s-%04d", city3, last3, sequence);
237	    }
238	
239	    /**
240	     * Build the membership number assigned on create, formatted
241	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
242	     * {@code registrationDate} year (e.g. 'LON-SMI-0007-M26').
243	     */
244	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
245	        String yy = String.format("%02d", registrationDate.getYear() % 100);
246	        return customerCode + "-M" + yy;
247	    }
