100	
101			private String objectName;
102			private String fieldName;
103			private String fieldValue;
104			private String errorMessage;
105	
106			public BindingError() {
107				this.objectName = "";
108				this.fieldName = "";
109				this.fieldValue = "";
110				this.errorMessage = "";
111			}
