17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.stereotype.Component;
20	
21	/**
22	 * Normalises a raw telephone number to the single canonical form under which it is both
23	 * stored and compared for duplicates.
24	 *
25	 * <p>Keeping this in one place means the stored form and the form used to detect duplicate
26	 * telephones can never drift apart: an owner is a duplicate of another exactly when their
27	 * telephones normalise to the same value.
28	 *
29	 * <p>The canonical form is E.164: a leading '+' followed by 8 to 15 digits. A number that
30	 * already carries a leading '+' keeps its explicit country code; otherwise country code
31	 * '+61' is assumed and a single leading '0' is dropped from the national digits. Spaces,
32	 * dashes and brackets are stripped. Anything that cannot reduce to a '+' plus 8 to 15 digits
33	 * has no canonical form.
34	 */
35	@Component
36	public class TelephoneNormalizer {
37	
38	    private static final String DEFAULT_COUNTRY_CODE = "61";
39	
40	    private static final int MIN_DIGITS = 8;
41	
42	    private static final int MAX_DIGITS = 15;
43	
44	    /**
45	     * Reduce a raw telephone to its canonical E.164 stored form.
46	     *
47	     * @param rawTelephone the telephone as supplied by the client, possibly {@code null} or
48	     *                     containing spaces, dashes or brackets
49	     * @return the canonical E.164 telephone (a '+' followed by 8 to 15 digits), or
50	     *         {@code null} if {@code rawTelephone} cannot form a valid E.164 number
51	     */
52	    public String normalize(String rawTelephone) {
53	        if (rawTelephone == null) {
54	            return null;
55	        }
56	        String trimmed = rawTelephone.trim();
57	        boolean hasCountryCode = trimmed.startsWith("+");
58	        String digits = trimmed.replaceAll("\\D", "");
59	        if (!hasCountryCode) {
60	            if (digits.startsWith("0")) {
61	                digits = digits.substring(1);
62	            }
63	            digits = DEFAULT_COUNTRY_CODE + digits;
64	        }
65	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
66	            return null;
67	        }
68	        return "+" + digits;
69	    }
70	}
