17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.Locale;
20	import java.util.Map;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Normalises a raw postal address to the single canonical form under which it is both
26	 * stored and compared.
27	 *
28	 * <p>Keeping this in one place means the stored form and the form used for household
29	 * duplicate detection and the shared household id can never drift apart: two owners
30	 * belong to the same household exactly when their addresses normalise to the same value.
31	 *
32	 * <p>The canonical form trims surrounding whitespace, collapses internal whitespace runs
33	 * to a single space, upper-cases every character, and expands the common street-type
34	 * abbreviations ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) that
35	 * appear as whole words. An address consisting only of whitespace normalises to the empty
36	 * string.
37	 */
38	@Component
39	public class AddressNormalizer {
40	
41	    /** Whole-word street-type abbreviations expanded to their canonical form (keys are
42	     *  already upper-cased, matching the point at which they are applied). */
43	    private static final Map<String, String> ABBREVIATIONS = Map.of(
44	        "ST", "STREET",
45	        "RD", "ROAD",
46	        "AVE", "AVENUE");
47	
48	    /**
49	     * Reduce a raw address to its canonical stored form.
50	     *
51	     * @param rawAddress the address as supplied by the client, possibly {@code null} or
52	     *                   containing irregular whitespace, casing and abbreviations
53	     * @return the canonical address (trimmed, whitespace-collapsed, upper-cased and with
54	     *         common abbreviations expanded), or the empty string if {@code rawAddress} is
55	     *         {@code null} or blank
56	     */
57	    public String normalize(String rawAddress) {
58	        if (rawAddress == null) {
59	            return "";
60	        }
61	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
62	        if (collapsed.isEmpty()) {
63	            return "";
64	        }
65	        String[] words = collapsed.split(" ");
66	        StringBuilder sb = new StringBuilder(collapsed.length());
67	        for (int i = 0; i < words.length; i++) {
68	            if (i > 0) {
69	                sb.append(' ');
70	            }
71	            sb.append(ABBREVIATIONS.getOrDefault(words[i], words[i]));
72	        }
73	        return sb.toString();
74	    }
75	}
